  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (610::BIGINT, 'Si de verdad le interesa la carrera, le va a caer excelente el docente, responde todas sus dudas con la intencion de que aprenda y no te regale la respuesta y hace el curso (que es muy pesado) muy llevadero. Simplemente la cabra'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-09-24T00:00:00+00:00'::TIMESTAMPTZ, 'b667e564f8e4c2a3ba9ac6047ff958073021cc76db0bc070761c9a37f5fdbb1a'::TEXT, ARRAY[1710, 1850]::BIGINT[]),
    (610::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'b0126e9c0024e97a1a2cea295a4b1c9f9c64753c43199f8313f7109da0ec0034'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Increíble persona, increíble profesor, Increíble en todo aspecto. Ni lo dude, matricule con él, lo va a amar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'eab981428be5c131d184832c58c1ca26f1e3cb3e4e64fc8099fe2cbe771dc221'::TEXT, ARRAY[1850, 1710]::BIGINT[]),
    (610::BIGINT, 'Excelente profesor, es un amigo más. Las tareas son muy chivas, algo largas pero todo bien. Califica normal, de fijo se aprende como con ningún otro profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'baeac36ca1b457ed2582124b69a924f5f27b63f332678ec8689d21294125e6dd'::TEXT, ARRAY[1850]::BIGINT[]),
    (610::BIGINT, 'Es demasiado bueno, de fijo es un profe que vale la pena, si usted quiere tener buenas bases, este es su profe. Tareas chivas y creativas, eso si, son bastante largas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '26984d873a4436adb9f38aa393f740ba6721bc2954f30708381758c01cedc131'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-06-16T00:00:00+00:00'::TIMESTAMPTZ, '16556cb637d3be1822f9fe628d210910df866e00f248eceb85f5cc08d0d1485c'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'El profe es muy buena gente pero al explicar las tareas a veces no es tan claro en qué es lo que quiere específicamente y tiende a confundir. Pero en general, es un curso muy llevadero y con un buen grupo de trabajo se saca adelante fácilmente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-02-02T00:00:00+00:00'::TIMESTAMPTZ, '45a84b68dc6a3f7c05b7b30099bd961ab2e739badc349d23363e9725f00cf7e9'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'El profe es súper carismático, se nota que le gusta dar clases solo que a veces no es tan claro para lo que quiere en los trabajos. Tiene todo el material de clase digitalizado, lo cual es muy útil para no perderse en las clases. Todos los trabajos son en grupo y él los hace'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cf85801fece359835e3496d02193aeddf471f1387929ab2d9f7c42c3a552adf4'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'Es una teja de profe, todo lo deja en video y la clase es idéntica.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '0b1488a182ebc7b0fb4ec0f041f61b53776518f7bbccb70839ed0f94a5678ad9'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'No es claro en algunas ocasiones con lo que quiere en los trabajos y a veces responde de manera poco paciente, pero como persona es genial, además de que está muy bien preparado profesionalmente.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9a0f3c586c6535ee5c04b22abcd19f17175dcbf38fbf5f4999a11ac71d543d91'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, '10/10. Al principio uno piensa que es un poco estricto, pero después se le agarra cariño. Es muy sarcástico y le gusta vacilar. La materia es súper interesante y se ve que sabe del tema. Como también es psicopedagogo, enfatiza mucho en el manejo del estrés y brinda apoyo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2023-06-07T00:00:00+00:00'::TIMESTAMPTZ, '13124f64e0f230d5fdb7fb1f5be5d50b1a967e523f8a5ee003556c110fdd6965'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'Al principio tenía miedo por los comentarios de que era un profesor odioso, pero lo terminé amando. Es uno de los mejores profesores. Las primeras tareas califica duro, pero es para que uno observe los errores y no cometerlos en el proyecto. Es muy unido a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2021-12-16T00:00:00+00:00'::TIMESTAMPTZ, '8538779540b446f62720da96dd55f1b34daa2a3ac269f808de66762604457ec0'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'dba2b7b4be9a33f3913c365ab8c6c55587249a28f33debd4664992c84da71f65'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Es una teja de profe. Al principio pensé que era muy carepich*, pero a final de semestre lo terminé amando. Se aprende muchísimo con él, y siempre está dispuesto a ayudar y a dar consulta. No se desanime si le va mal en las primeras tareas, no valen tanto y al final le va a ir muy bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '9847dc174fbbdaa8ae94185cb8068dcb5f2755154bd001aec19bb4cf0657e6a3'::TEXT, ARRAY[1710, 1845]::BIGINT[]),
    (610::BIGINT, 'El profe es exigente pero da muy buena retroalimentación en todos los trabajos, se apega a la rúbrica para evaluar y busca la excelencia en los estudiantes. Se esfuerza mucho porque aprendan y aclara dudas con mucha amabilidad. Sus clases son asincrónicas y una vez a la semana hay consulta'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'faa4469479da111a9d994e0463e02d9ab9d938a35ec8b7e7bac18e8e4c369056'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'Es un profe que sabe mucho y siempre se muestra dispuesto a ayudar a los estudiantes. Es bastante organizado, da muy buena retroalimentación (aunque a veces un poco dura) y comunicarse con él es fácil. Sin embargo, en algunos casos hace preguntas o comentarios que pueden ser un tanto intimidantes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '35cc5f5705893bfdeb5b77465f241b574b9f6f636120ad13b0e865dc5a1c37e2'::TEXT, ARRAY[1710]::BIGINT[]),
    (610::BIGINT, 'Es buen profe y ayuda mucho si uno se lo pide, pero trata demasiado de ser “el buena gente” y a veces se le va la mano con la retroalimentacion que da, califica muy duro y dice cosas fuera de lugar en algunos casos. Igual lo escogeria de nuevo porque hace q la clase se vuelva mas facil.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'c2a5685ac876aec5973911ce0643e95030b27997a7f5b0bb6a62e757e564fb05'::TEXT, ARRAY[1873, 1868, 1867, 1860, 1859]::BIGINT[]),
    (610::BIGINT, 'Se aprende mucho, pero califica MUY rudo. Solo él tiene la razón, reclamarle es prácticamente imposible. Su curso (vale 2 créditos) y toma más tiempo que los de 4. Lo bueno es que está dispuesto a dar retroalimentación y aclarar dudas.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-14T00:00:00+00:00'::TIMESTAMPTZ, '5d5c986bb1a5b5c01cac697257d0e0be48bada08d84d2e6f5c478975538472f1'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Muy buen profe aunque califica un poco rudo, se nota que le gusta enseñar y brinda mucho apoyo a los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'ba7f51934e0182f3036f674f09dfe4a87bc483ece4a08ebfbf74b4ea6e3d59bc'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Puede ser un buen profesor, pero le encanta dejar en ridículo para lucirse él. El curso puede ser fácil, es más que todo detalle. Llegue preparado para el Bulling didáctico dice él, yo creo que es más bien un miedo que no superó nunca. Se enoja sólo. No será más fácil hablar claro?'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-03-02T00:00:00+00:00'::TIMESTAMPTZ, 'bfb3c4da1059a46f4b6bcb0b3c7d83d224606664847fedad1cbea0b78d110e48'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'Es muy duro revisando en los primeros cursos porque su intención es que uno aprenda. Excelente profesor, sabe mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bef94d1d555b50f22d1f32c56669a52cc58a8d5e407cf89e08eeb3565b25c658'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Es el profesor que se quiere hacer amigo de los estudiantes. Tanto así que olvida un poco formar mejor a sus estudiantes y a sí mismo (su diseño deja mucho que desear). Tiene favoritismos y si no lo alabás automáticamente le caes mal. Juega de muy buena gente y cool hasta que se le mete el diablo'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes']::TEXT[], '2019-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'bec22a68c0bd0f3a044ce7e9128d1ceda4bb46cb889cb1138857b5db12aba0a3'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Las instrucciones no son claras, ni su forma de evaluar, por lo tanto califica durísimo. Además no crea un ambiente de respeto, más bien no dan ganas de ir a clase (aún peor cuando anda enojado).'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos proyectos grupales']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '04f96c943fe6ea00b3349e415634923ede24214226f8c433d467f57618d62fdc'::TEXT, ARRAY[1845, 1709]::BIGINT[]),
    (610::BIGINT, 'Si usted no va a consulta se va a quedar, pero igual si va a consulta lo va a tratar mal y si usted le cae mal, mejor mátese, porque en clase lo va a dejar mal frente a toda la clase, califica horrible y muy duro'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '3ea1b3f3605f095b05d42cbe1c408bba9b43ee12a72d8ed140f7575c65ea49e7'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-06T00:00:00+00:00'::TIMESTAMPTZ, '59682c271f388a7adddb5d347755f0b1cccdc78ea9aabe0441d2dafb094ba044'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'excelente profesor, le encanta enseñar y da el curso de manera en que uno aprenda. trata de dar el curso con la cantidad de créditos que son y siempre está disponible para consultas. a veces se molesta si no puede dar la clase, pero sabe muy bien cómo manejar la lección.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b396b7238eda2131da3a2d82c8f59acd0bb105dcde602f8d0b17d814f675244d'::TEXT, ARRAY[1850]::BIGINT[]),
    (610::BIGINT, 'Buen profesor, disponible casi siempre. Le gusta mucho alabarse, hay que seguirle la corriente.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-21T00:00:00+00:00'::TIMESTAMPTZ, '3a04ac5ceaa836af278ea707d3290f47a3dc6e88313cc701ad09db626e3d5cac'::TEXT, ARRAY[1850]::BIGINT[]),
    (610::BIGINT, 'Las clases son sumamente entretenidas (solo que a veces anda de mal humor) pero en general las dinámicas son super divertidas. HAY QUE IR A CONSULTA, a veces uno cree que lo hizo bien pero está todo mal porque no es muy claro con las instrucciones, enserio vaya a consulta para pasar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2018-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'fa1c67778749604e20f8078458a90d8851b3c7a924e028a9e6f14ce84131140a'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1ad0b93b70ff75c7d0ec91f03d5bf9924b2396b83c84f8863adcd491253a3615'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'Súper buen profe, muy inspiracional. Eso sí, para los trabajos SIEMPRE hay que ir a consulta y él lo guía a uno bastante. Y atiene casi siempre, aunque no esté propiamente en hora de consulta.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '75c294019f96f1473c99b8f743e8d17e6757ea959f11af5e281353fcdf325177'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Donald es el mejor, tiene una pasión única por lo que hace y es increíblemente creativo. Hay que ir mucho a consulta para hacer bien los trabajos, pero él casi siempre lo atiende a uno si está en la oficina (incluso fuera de horario de consulta). Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '93af42456bb956b52ad8cb4af150d1d247acf394d0d5bf4259afa7bb1ca65aa0'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7cb1d3694bde9ca4a00d01f19a397dd965d9456a06b6524bada3ee6134264d08'::TEXT, ARRAY[1709]::BIGINT[]),
    (610::BIGINT, 'Si no va a consulta muere'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, '67d12e7c81129bc5cd9893ede1f2e255c73bc648af89db7190a20b636e30bd44'::TEXT, ARRAY[1845]::BIGINT[]),
