    (610::BIGINT, 'Simplemente el mejor Profe de diseño'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '61cbae9f2caf2473dd455e6dc271dad23d12cb50acd31da130e1153d53c357b9'::TEXT, ARRAY[1845]::BIGINT[]),
