    (610::BIGINT, 'uno de los únicos profesores, que si estudiaron para profesores, ordenado y califica con rublos definidos, el unico que se rescata de esa escuela'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'c8b47071f028c538ff2df6c780c9325d99e0dcafd25768bbc8a7d572d9d80fe2'::TEXT, ARRAY[1845]::BIGINT[]),
    (610::BIGINT, 'Es muy suave, aburre con cosas de cocina y del principito pero podes pasar el curso sin matarte, solo llevale cosas bonitas y siguele el juego eso si jamás le lleves la contraria que el curso es aburrido'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-19T00:00:00+00:00'::TIMESTAMPTZ, '75e52be7a120228c39c07f4cc15059e96c3126892da1f69c0425a9b4f8920413'::TEXT, ARRAY[1845]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
